package streamix.readingcatalog
import org.jsoup.Jsoup
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull
import kotlinx.coroutines.runBlocking
class AdditionalIndonesianManhwaRuntimeProviderTest {
 @Test fun voratoonUsesChapterApi()=runBlocking{var url="";val p=VoraToonReadingRuntimeProvider{u->url=u;"""{"data":{"data":{"images":["https://cdn.voratoon.com/1.jpg"]}}}"""};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://v9.voratoon.com/series/slug",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","voratoon","https://v9.voratoon.com/series/slug/chapter/1")));assertEquals(true,p.supports(e,c));val result=p.chapter(e,c);assertEquals("https://v9.voratoon.com/api/proxy/series/slug/chapters/1",url);assertEquals(listOf("https://cdn.voratoon.com/1.jpg"),result?.pageUrls)}
 @Test fun comicasoUsesTokenizedChapterApi()=runBlocking{var url="";val p=ComicasoReadingRuntimeProvider{u->url=u;"""{"data":{"images":["https://cdn.comicaso.pro/1.jpg"]}}"""};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://v3.comicaso.pro/all/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","comicaso","https://v3.comicaso.pro/all/title/ch-1?token=abc")));assertEquals(true,p.supports(e,c));val result=p.chapter(e,c);assertEquals("https://v3.comicaso.pro/api/chapter.php?source=all&manga=title&chapter=ch-1&token=abc",url);assertEquals(listOf("https://cdn.comicaso.pro/1.jpg"),result?.pageUrls)}
 @Test fun voratoonSkipsDataUriAndFallsBackToSrc()=runBlocking{val p=VoraToonReadingRuntimeProvider{"""{"data":{"images":[{"url":"data:image/gif;base64,placeholder","src":"https://cdn.voratoon.com/fallback.jpg"}]}}"""};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://v9.voratoon.com/series/slug",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","voratoon","https://v9.voratoon.com/series/slug/chapter/1")));assertEquals(listOf("https://cdn.voratoon.com/fallback.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun comicasoSkipsDataUriAndFallsBackToSrc()=runBlocking{val p=ComicasoReadingRuntimeProvider{"""{"data":{"images":[{"url":"data:image/gif;base64,placeholder","src":"https://cdn.comicaso.pro/fallback.jpg"}]}}"""};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://v3.comicaso.pro/all/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","comicaso","https://v3.comicaso.pro/all/title/ch-1?token=abc")));assertEquals(listOf("https://cdn.comicaso.pro/fallback.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun theMangaUsesPageImgSelector()=runBlocking{val p=TheMangaReadingRuntimeProvider{u->Jsoup.parse("""<img class="page-img" src="/1.jpg">""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://themanga.site/manga/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","the-manga","https://themanga.site/manga/title/chapter/1")));assertEquals(listOf("https://themanga.site/1.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun theMangaFallsBackToDataOriginalAndSkipsDataUri()=runBlocking{val p=TheMangaReadingRuntimeProvider{u->Jsoup.parse("""<img class="page-img" data-original="/original.jpg" src="data:image/gif;base64,placeholder">""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://themanga.site/manga/title",ReadingEntryOrigin.MANUAL);val ch=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","the-manga","https://themanga.site/manga/title/chapter/1")));assertEquals(listOf("https://themanga.site/original.jpg"),p.chapter(e,ch)?.pageUrls)}
 @Test fun ulasComicUsesReaderMarkupAndOriginalImageFallback()=runBlocking{val p=UlasComicReadingRuntimeProvider{u->Jsoup.parse("""<div class="check-box"><div class="separator"><img data-original="/original.jpg" src="data:image/gif;base64,placeholder"><img src="/1.jpg"></div></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://www.ulascomic01.xyz/komik/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","ulas-comic","https://www.ulascomic01.xyz/chapter/title")));assertEquals(listOf("https://www.ulascomic01.xyz/original.jpg","https://www.ulascomic01.xyz/1.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun voratoonAcceptsCurrentRedirectingV1HostButRejectsRetiredCoHost()=runBlocking{val p=VoraToonReadingRuntimeProvider{error("must not fetch")};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://v9.voratoon.com/series/slug",ReadingEntryOrigin.MANUAL);val current=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","voratoon","https://v1.voratoon.com/series/slug/chapter/1")));val retired=ReadingChapterEntry("c2","1",sources=listOf(ReadingChapterSource("s2","voratoon","https://voratoon.co/series/slug/chapter/1")));assertEquals(true,p.supports(e,current));assertEquals(false,p.supports(e,retired));assertEquals(null,p.chapter(e,retired))}
 @Test fun voratoonRejectsPathTraversalSegmentsBeforeFetching()=runBlocking{val p=VoraToonReadingRuntimeProvider{error("must not fetch")};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://v9.voratoon.com/series/slug",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","voratoon","https://v9.voratoon.com/series/../chapter/1")));assertEquals(false,p.supports(e,c));assertNull(p.chapter(e,c))}
 @Test fun rejectsForeignChapterHost()=runBlocking{val p=VoraToonReadingRuntimeProvider{error("must not fetch")};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://v9.voratoon.com/series/slug",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","voratoon","https://evil.example/series/slug/chapter/1")));assertEquals(false,p.supports(e,c));assertNull(p.chapter(e,c))}
 @Test fun rejectsEmptyChapterApiPayload()=runBlocking{val p=ComicasoReadingRuntimeProvider{"""{"data":{"images":[]}}"""};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://v3.comicaso.pro/all/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","comicaso","https://v3.comicaso.pro/all/title/ch-1?token=abc")));assertNull(p.chapter(e,c))}
}
